<script lang="ts">
 import {goto} from '$app/navigation';import {app,run} from '../app.svelte';import {claimStore} from '../store';import {statuses} from '../types';import {money,total} from '../money';import Icon from '../components/Icon.svelte';import ClaimsTable from '../components/ClaimsTable.svelte';import {download,exportCSV} from '../exports';import {todayLocal} from '../sample';
 let {mode='employee'}:{mode?:'employee'|'manager'|'finance'}=$props();let search=$state(''),status=$state('All statuses'),from=$state(''),to=$state(''),sort=$state('newest');
 $effect(()=>{status=mode==='manager'?'Submitted':mode==='finance'?'Manager approved':'All statuses';});
 const data=$derived(app.data!);const list=$derived(data.claims.filter(c=>(status==='All statuses'||c.status===status)&&(!from||(c.submittedAt||c.createdAt).slice(0,10)>=from)&&(!to||(c.submittedAt||c.createdAt).slice(0,10)<=to)&&`${c.number} ${c.title} ${c.costCentre} ${data.users.find(u=>u.id===c.ownerId)?.name||''}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='amount'?total(b.lines)-total(a.lines):sort==='oldest'?a.updatedAt.localeCompare(b.updatedAt):b.updatedAt.localeCompare(a.updatedAt)));
 async function create(){const c=await run(()=>claimStore.create());if(c)goto('/claims/'+c.id);}
 function exportList(){download(exportCSV('claims',{...data,claims:list},todayLocal(),c=>claimStore.findings(c)),'claimease-claims.csv','text/csv');}
</script>
<div class="page-header"><div><p class="eyebrow">{mode==='employee'?'KEEP EVERY EXPENSE IN SIGHT':mode==='manager'?'MANAGER WORKSPACE':'FINANCE WORKSPACE'}</p><h1>{mode==='employee'?'My claims':mode==='manager'?'Approval inbox':'Finance queue'}</h1><p>{mode==='employee'?'Draft, track and manage your expense claims.':mode==='manager'?'Review your team’s claims. Clear decisions, complete history.':'Review approved claims and prepare reimbursements.'}</p></div>{#if mode==='employee'}<button class="primary" onclick={create}><Icon name="plus" size={18}/>New claim</button>{:else if mode==='finance'}<a class="button primary" href="/batches"><Icon name="wallet" size={18}/>Create payment batch</a>{:else}<a class="button" href="/dashboard"><Icon name="chart" size={18}/>Team dashboard</a>{/if}</div>
{#if mode!=='employee'}<div class="queue-summary"><div><span class="summary-icon"><Icon name="clock"/></span><div><strong>{data.claims.filter(c=>c.status===(mode==='manager'?'Submitted':'Manager approved')).length} waiting for review</strong><p>Only claims available to your role are shown.</p></div></div><div><span>Pending amount</span><strong>{money(total(data.claims.filter(c=>c.status===(mode==='manager'?'Submitted':'Manager approved')).flatMap(c=>c.lines),true))}</strong></div>{#if mode==='manager'}<div><span>Over 3-day SLA</span><strong>{data.claims.filter(c=>c.status==='Submitted'&&Date.now()-Date.parse(c.submittedAt!)>3*86400000).length} claims</strong></div>{/if}</div>{/if}
<section class="panel"><div class="filter-bar"><label class="search-field"><span class="sr-only">Search claims</span><Icon name="search" size={18}/><input bind:value={search} placeholder="Search purpose, claim number or cost centre"/></label><label><span class="sr-only">Filter by status</span><select aria-label="Filter by status" bind:value={status}><option>All statuses</option>{#each statuses as s}<option>{s}</option>{/each}</select></label><button onclick={exportList}><Icon name="download" size={17}/>Export CSV</button></div><div class="secondary-filters"><label>From<input type="date" bind:value={from}/></label><label>To<input type="date" bind:value={to}/></label><label>Sort<select bind:value={sort}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="amount">Highest amount</option></select></label><span>{list.length} claims <span class="separator">·</span> <strong>{money(total(list.flatMap(c=>c.lines)))}</strong></span></div><ClaimsTable claims={list} users={data.users} team={mode!=='employee'}/></section>
<p class="table-note"><Icon name="lock" size={14}/>{mode==='employee'?'Only your own claims are visible here.':mode==='manager'?'Only employees assigned to you as primary or second-level manager are visible.':'Amounts are in INR. Payment batches record reimbursements; they do not transfer money.'}</p>